const AsyncF=Object.getPrototypeOf(async function(){}).constructor;
try{await new AsyncF("p","c","shot","dump",steps)(p,c,shot,dump);}catch(e){console.log("ERR",e.message.split("\n")[0]);await shot("error");}
await b.close();
EOF
